connected_planning_status_v1 plan_connected_cross_tu_chain_v1(const connected_relation_chain_v1&q,connected_planning_result_v1*r)noexcept{if(!r)return connected_planning_status_v1::body_unavailable;*r={};r->materialized_total_ns=q.producer_ns+q.consumer_ns+q.materialize_ns+q.order_transition_ns;r->selected_total_ns=r->materialized_total_ns;if(!q.semantic_body_available)return connected_planning_status_v1::body_unavailable;if(!q.authorized)return connected_planning_status_v1::unauthorized;if(!q.effects_permit_inline)return connected_planning_status_v1::effect_boundary;r->semantic_inlined=true;r->persistent_order=!q.producer_order.empty()&&q.producer_order==q.consumer_order;r->shared_decomposition=!q.producer_decomposition.empty()&&q.producer_decomposition==q.consumer_decomposition;r->selected_total_ns=q.producer_ns+q.consumer_ns+(r->persistent_order?0:q.order_transition_ns)+(r->semantic_inlined?0:q.materialize_ns);return connected_planning_status_v1::valid;}
